"""Vonage Voice API WebSocket stream integration.

Vonage's WebSocket model:

* Your server is the WebSocket endpoint and Vonage opens the connection.
* The first frame is a ``websocket:connected`` JSON text frame describing the
  negotiated ``content-type`` and any custom headers from the NCCO ``connect``
  action. Bidirectional audio (20 ms little-endian L16 PCM) follows as binary
  frames.
* Control commands are exchanged as JSON text frames: outbound ``clear`` and
  ``notify``, inbound ``websocket:cleared`` and ``websocket:notify``. We use
  ``notify`` as the marker mechanism that drives bot-speaking state, end-of-
  utterance hangup, and barge-in.

References:
* WebSockets concept: https://developer.vonage.com/en/voice/voice-api/concepts/websockets
* Webhook reference: https://developer.vonage.com/en/voice/voice-api/webhook-reference
* AI agent example: https://developer.vonage.com/en/voice/voice-api/guides/voice-ai-agent-deepgram
"""

from __future__ import annotations

import json
import uuid
from typing import Any, Dict, List, Optional, Text, Union

import structlog
from sanic import (  # type: ignore[attr-defined]
    Blueprint,
    HTTPResponse,
    Request,
    Websocket,
    response,
)

from rasa.core.channels.channel import RuntimeAgent
from rasa.core.channels.voice_ready.utils import (
    CallParameters,
    validate_username_password_credentials,
)
from rasa.core.channels.voice_stream.audio_bytes import (
    L16_24KHZ,
    RasaAudioBytes,
)
from rasa.core.channels.voice_stream.call_state import (
    BotIsSpeaking,
    BotStoppedSpeaking,
    Marker,
    MarkerType,
    call_state,
)
from rasa.core.channels.voice_stream.tts.tts_engine import TTSEngine
from rasa.core.channels.voice_stream.util import repack_voice_credentials
from rasa.core.channels.voice_stream.voice_channel import (
    ContinueConversationAction,
    EndConversationAction,
    MarkerInput,
    MarkerMessageOutput,
    NewAudioAction,
    VoiceChannelAction,
    VoiceInputChannel,
    VoiceOutputChannel,
)

logger = structlog.get_logger(__name__)

VONAGE_WEBSOCKET_PATH = "webhooks/vonage/websocket"
VONAGE_CALL_STATUS_PATH = "webhooks/vonage/call_status"

# Vonage inbound event names sent on the WebSocket.
VONAGE_CONNECTED_EVENT = "websocket:connected"
VONAGE_NOTIFY_EVENT = "websocket:notify"
VONAGE_CLEARED_EVENT = "websocket:cleared"

# Top-level fields in the ``websocket:connected`` frame that aren't custom
# headers from the NCCO ``connect`` action.
_VONAGE_SYSTEM_FIELDS = frozenset({"event", "content-type"})


def _normalize_server_url(server_url: Text) -> Text:
    """Strip whitespace and trailing slashes; require a non-empty value."""
    base_url = server_url.strip().rstrip("/")
    if not base_url:
        raise ValueError("Vonage stream server_url must be configured")
    return base_url


def _public_event_url(server_url: Text) -> Text:
    """Build the ``https://`` URL Vonage should POST call-status events to."""
    base_url = _normalize_server_url(server_url)

    if base_url.startswith("ws://"):
        base_url = f"http://{base_url[len('ws://'):]}"
    elif base_url.startswith("wss://"):
        base_url = f"https://{base_url[len('wss://'):]}"
    elif not base_url.startswith(("http://", "https://")):
        base_url = f"https://{base_url}"

    return f"{base_url}/{VONAGE_CALL_STATUS_PATH}"


def _json_phone_field(payload: Dict[str, Any], key: Text) -> str:
    """Return a phone number string from a Vonage answer-webhook field.

    Vonage's answer webhook delivers ``from``/``to`` as plain strings, but the
    same callback shape is used elsewhere with ``{"type": "phone", "number":
    "..."}`` objects. Accept both so the channel works with either source.
    """
    raw = payload.get(key)
    if raw is None:
        return ""
    if isinstance(raw, dict):
        return str(raw.get("number") or "")
    return str(raw)


def _answer_payload(request: Request) -> Dict[str, Any]:
    """Extract answer-webhook fields from query args, form, or JSON body.

    Vonage's default ``answer_method`` is ``GET`` with the call parameters in
    the query string; operators can configure ``POST`` with a JSON body. We
    also accept ``application/x-www-form-urlencoded`` defensively.
    """
    if request.args:
        return {key: request.args.get(key) for key in request.args}
    if request.form:
        return {key: request.form.get(key) for key in request.form}
    if isinstance(request.json, dict):
        return dict(request.json)
    return {}


def _vonage_connect_ncco(
    websocket_url: Text,
    event_url: Text,
    content_type: Text,
    answer: Dict[str, Any],
) -> List[Dict[str, Any]]:
    """Build an NCCO that connects the call leg to this server's WebSocket.

    The NCCO uses ``eventType: synchronous`` so Vonage will POST
    ``unanswered``/``failed`` events to ``event_url`` before considering the
    setup complete (allowing a fallback NCCO to be returned), and so
    ``disconnected`` events for the live leg are delivered there too. Custom
    headers carry call identifiers Vonage echoes back on the WebSocket
    ``websocket:connected`` frame.
    """
    call_uuid = str(answer.get("uuid") or "")
    conversation_uuid = str(answer.get("conversation_uuid") or "")
    user_phone = _json_phone_field(answer, "from")
    bot_phone = _json_phone_field(answer, "to")
    direction = str(answer.get("direction") or "")

    connect: Dict[str, Any] = {
        "action": "connect",
        "eventType": "synchronous",
        "eventUrl": [event_url],
        "endpoint": [
            {
                "type": "websocket",
                "uri": websocket_url,
                "content-type": content_type,
                "headers": {
                    "call_id": call_uuid,
                    "conversation_id": conversation_uuid,
                    "user_phone": user_phone,
                    "bot_phone": bot_phone,
                    "direction": direction,
                },
            }
        ],
    }
    if user_phone:
        # Preserve the caller ID on the new (WebSocket) call leg.
        connect["from"] = user_phone
    return [connect]


def map_call_params(data: Dict[str, Any]) -> CallParameters:
    """Map the Vonage initial WebSocket JSON message to ``CallParameters``.

    Only the custom headers we set in the NCCO ``connect`` action survive into
    ``CallParameters`` — Vonage's own envelope fields (``event``,
    ``content-type``) are filtered out so they don't leak into call metadata.
    """
    headers = {
        str(k): str(v)
        for k, v in data.items()
        if str(k).lower() not in _VONAGE_SYSTEM_FIELDS
    }
    call_id = headers.get("call_id", "")
    conversation_id = headers.get("conversation_id", "")
    return CallParameters(
        call_id=call_id,
        user_phone=headers.get("user_phone", ""),
        bot_phone=headers.get("bot_phone") or None,
        direction=headers.get("direction") or None,
        stream_id=conversation_id or call_id or None,
    )


class VonageOutputChannel(VoiceOutputChannel):
    """Send linear PCM to Vonage as binary WebSocket frames."""

    @classmethod
    def name(cls) -> str:
        return "vonage"

    async def send_audio_bytes(
        self, recipient_id: str, audio_bytes: RasaAudioBytes
    ) -> None:
        """Send raw L16 PCM; Vonage expects binary frames after the metadata."""
        await self.voice_websocket.send(audio_bytes.data)

    def create_marker_message(self, marker_input: MarkerInput) -> MarkerMessageOutput:
        """Build a Vonage ``notify`` command used as an audio-stream marker.

        Vonage echoes the ``payload`` back via ``websocket:notify`` once the
        audio that was buffered when the command was queued has finished
        playing — the marker semantics that the parent ``VoiceOutputChannel``
        relies on for bot-speaking state, end-of-utterance hangup, and
        barge-in.
        """
        message_id = uuid.uuid4().hex
        notify_message = json.dumps(
            {
                "action": "notify",
                "payload": {"name": message_id},
            }
        )

        if marker_input.marker_type in {MarkerType.START, MarkerType.END}:
            call_state.set_marker(
                Marker(
                    marker_id=message_id,
                    marker_type=marker_input.marker_type,
                    step_type=marker_input.step_type,
                )
            )

        return MarkerMessageOutput(message_id=message_id, message=notify_message)


class VonageInputChannel(VoiceInputChannel):
    """Vonage Voice API WebSocket input channel."""

    def __init__(
        self,
        server_url: str,
        asr_config: Dict,
        tts_config: Dict,
        interruptions: Optional[Dict[str, int]] = None,
        silence_timeout: Optional[Union[float, int]] = None,
        username: Optional[Text] = None,
        password: Optional[Text] = None,
    ) -> None:
        super().__init__(
            server_url=server_url,
            asr_config=asr_config,
            tts_config=tts_config,
            interruptions=interruptions,
        )
        self.username = username
        self.password = password
        self.silence_timeout = silence_timeout
        self.audio_format = L16_24KHZ
        self.content_type = "audio/l16;rate=24000"

    @classmethod
    def from_credentials(
        cls,
        credentials: Optional[Dict[str, Any]],
    ) -> VoiceInputChannel:
        cls.validate_credentials(credentials)
        new_creds = repack_voice_credentials(credentials)
        return cls(**new_creds)

    @classmethod
    def validate_credentials(
        cls,
        credentials: Optional[Dict[str, Any]],
    ) -> None:
        """Validate the credentials dictionary used to construct the channel."""
        cls.validate_basic_credentials(credentials)
        username = credentials.get("username") if credentials else None
        password = credentials.get("password") if credentials else None
        validate_username_password_credentials(username, password, "Vonage Stream")

    def _websocket_stream_url(self) -> Text:
        """Return the websocket stream URL."""
        # depending on the config value, the url might contain http as a
        # protocol or not - we'll make sure both work
        if self.server_url.startswith("http"):
            base_url = self.server_url.replace("http", "ws")
        else:
            base_url = f"wss://{self.server_url}"
        return f"{base_url}/{VONAGE_WEBSOCKET_PATH}"

    @classmethod
    def name(cls) -> str:
        return "vonage"

    def get_sender_id(self, call_parameters: CallParameters) -> str:
        """Get the sender ID for the channel.

        Vonage uses the Stream ID as Sender ID because
        it is required in OutputChannel.send_text_message to send messages.
        """
        return call_parameters.stream_id  # type: ignore[return-value]

    def channel_bytes_to_rasa_audio_bytes(self, input_bytes: bytes) -> RasaAudioBytes:
        return RasaAudioBytes(input_bytes, format=self.audio_format)

    async def collect_call_parameters(
        self,
        channel_websocket: Websocket,
        request: Optional[Any] = None,
    ) -> Optional[CallParameters]:
        """Read the ``websocket:connected`` JSON frame Vonage sends first.

        Returns ``None`` when the first frame is binary (a protocol violation
        we won't try to recover from) or when the stream closes before any
        text frame arrives.
        """
        logger.info("vonage.collect_call_parameters")
        async for message in channel_websocket:
            if isinstance(message, (bytes, bytearray)):
                logger.error(
                    "vonage.collect_call_parameters.unexpected_binary_first_frame",
                    length=len(message),
                )
                return None
            data = json.loads(message)
            received_event = data.get("event")
            if received_event and received_event != VONAGE_CONNECTED_EVENT:
                logger.error(
                    "vonage.collect_call_parameters.unexpected_first_event",
                    received_event=received_event,
                )
                return None
            logger.info("vonage.websocket_metadata", data=data)
            return map_call_params(data)
        return None

    async def map_input_message(
        self,
        message: Any,
        ws: Websocket,
    ) -> VoiceChannelAction:
        if isinstance(message, (bytes, bytearray)):
            audio = self.channel_bytes_to_rasa_audio_bytes(bytes(message))
            return NewAudioAction(audio)

        data = json.loads(message)
        event = str(data.get("event") or "")

        if event == VONAGE_NOTIFY_EVENT:
            return await self._handle_notify_event(data)

        if event == VONAGE_CLEARED_EVENT:
            # Acknowledgement of an outbound ``clear`` (barge-in). No state
            # change is required; the bot-speaking flag is driven by markers.
            logger.debug("vonage.cleared_ack", payload=data)
            return ContinueConversationAction()

        if event == VONAGE_CONNECTED_EVENT:
            logger.warning("vonage.unexpected_repeat_connected_event", payload=data)
            return ContinueConversationAction()

        logger.debug("vonage.unknown_json_message", payload=data)
        return ContinueConversationAction()

    async def _handle_notify_event(self, data: Dict[str, Any]) -> VoiceChannelAction:
        """Translate a Vonage ``websocket:notify`` into marker bookkeeping.

        Mirrors the ``mark`` event handling other voice-stream channels do:
        START markers transition the call into "bot speaking"; END markers
        transition it out and, when the bot requested hangup, end the call.
        """
        payload = data.get("payload") or {}
        marker_name = str(payload.get("name") or "")
        if not marker_name:
            return ContinueConversationAction()

        marker = call_state.get_marker(marker_name)
        if marker is None:
            return ContinueConversationAction()

        call_state.remove_marker(marker.marker_id)

        if marker.step_type:
            if marker.marker_type == MarkerType.START:
                call_state.current_bot_utterance_type = marker.step_type
                await call_state.enqueue_event(BotIsSpeaking())

            if marker.marker_type == MarkerType.END:
                call_state.current_bot_utterance_type = None
                await call_state.enqueue_event(BotStoppedSpeaking())
                if call_state.should_hangup:
                    logger.debug("vonage.hangup", marker=marker)
                    return EndConversationAction()

        return ContinueConversationAction()

    def create_output_channel(
        self, voice_websocket: Websocket, tts_engine: TTSEngine
    ) -> VoiceOutputChannel:
        """Build the matching output channel for this Vonage input channel."""
        return VonageOutputChannel(
            voice_websocket=voice_websocket,
            tts_engine=tts_engine,
            tts_cache=self.tts_cache,
            audio_format=self.audio_format,
        )

    async def interrupt_playback(
        self, ws: Websocket, call_parameters: CallParameters
    ) -> None:
        """Discard any buffered TTS audio on Vonage so barge-in is immediate."""
        logger.debug("vonage.interrupt_playback")
        await ws.send(json.dumps({"action": "clear"}))

    def conversation_blueprint(self, agent: RuntimeAgent) -> Blueprint:
        """Define a Sanic blueprint for the Vonage stream voice channel."""
        blueprint = Blueprint("vonage", __name__)

        @blueprint.route("/", methods=["GET"])
        async def health(_: Request) -> HTTPResponse:
            return response.json({"status": "ok"})

        @blueprint.route("/webhook", methods=["GET", "POST"])
        async def webhook(request: Request) -> HTTPResponse:
            answer = _answer_payload(request)
            websocket_url = self._websocket_stream_url()
            event_url = _public_event_url(self.server_url)
            ncco = _vonage_connect_ncco(
                websocket_url=websocket_url,
                event_url=event_url,
                content_type=self.content_type,
                answer=answer,
            )
            logger.info(
                "vonage.answer_webhook",
                method=request.method,
                call_id=answer.get("uuid"),
                conversation_uuid=answer.get("conversation_uuid"),
                websocket_url=websocket_url,
                event_url=event_url,
            )
            return response.json(ncco)

        @blueprint.route("/call_status", methods=["POST"])
        async def call_status(request: Request) -> HTTPResponse:
            logger.debug("vonage.call_status", request_data=request.json)
            return response.json({"status": "ok"})

        @blueprint.websocket("/websocket")  # type: ignore[misc]
        async def handle_message(request: Request, ws: Websocket) -> None:
            logger.info("vonage.handle_message")
            try:
                await self.run_audio_streaming(agent, ws)
            except Exception as e:
                logger.error("vonage.websocket_error", error=str(e))

        return blueprint
